"""Build the interactive offline research viewer."""
from __future__ import annotations
import json
from pathlib import Path
import numpy as np
import pandas as pd

REPORTS = Path("reports")
OUTPUT = REPORTS / "research_viewer.html"

def frame_payload(path: str) -> tuple[list[str], list[dict[str, object]]]:
    frame = pd.read_csv(REPORTS / path, index_col=0, parse_dates=True)
    return [str(x) for x in frame.index], [{str(k): (None if pd.isna(v) else float(v)) for k, v in row.items()} for _, row in frame.iterrows()]

def build_payload() -> dict[str, object]:
    stats = pd.read_csv(REPORTS / "backtest_stats.csv").to_dict("records")
    alpha = pd.read_csv(REPORTS / "alpha_backtest_stats.csv").to_dict("records")
    factors = pd.read_csv(REPORTS / "oos_latent_factor_moves.csv", index_col=0, parse_dates=True)
    fitted = pd.read_csv(REPORTS / "strategy_oos_fitted.csv", index_col=0, parse_dates=True)
    residual = pd.read_csv(REPORTS / "strategy_oos_residuals.csv", index_col=0, parse_dates=True)
    raw = pd.read_csv(REPORTS / "data/raw/daily_returns.csv", index_col=0, parse_dates=True)[fitted.columns].loc[fitted.index]
    loads = pd.read_csv(REPORTS / "frozen_factor_loadings.csv", index_col=0)
    order = pd.read_csv(REPORTS / "benchmark_cluster_order.csv")["ticker"].tolist()
    raw_corr, residual_corr = raw.corr(), residual.corr()
    scatter = []
    for i, left in enumerate(raw.columns):
        for right in raw.columns[i + 1:]:
            scatter.append({"a": left, "b": right, "raw": float(raw_corr.loc[left, right]), "residual": float(residual_corr.loc[left, right]), "delta": float(residual_corr.loc[left, right] - raw_corr.loc[left, right])})
    return {"stats": stats, "alpha": alpha, "factors": {"dates": [str(x.date()) for x in factors.index], "names": list(factors), "values": factors.fillna(0).to_numpy().tolist()}, "funds": {"dates": [str(x.date()) for x in fitted.index], "names": list(fitted), "raw": raw.fillna(0).to_numpy().tolist(), "fitted": fitted.fillna(0).to_numpy().tolist(), "residual": residual.fillna(0).to_numpy().tolist(), "betas": loads.to_dict("index")}, "benchmarks": order, "scatter": scatter}

def render(payload: dict[str, object]) -> str:
    data = json.dumps(payload, separators=(",", ":"))
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Factor Model Research Viewer</title><style>
:root{{--ink:#17282e;--muted:#68787b;--paper:#f4f1e8;--panel:#fffdf8;--line:#d5d4ca;--teal:#176b87;--green:#2f855a;--red:#b94a48;--blue:#2e67a5;--gold:#b87919}}*{{box-sizing:border-box}}body{{margin:0;background:var(--paper);color:var(--ink);font:15px/1.5 Georgia,serif;background-image:linear-gradient(rgba(23,107,135,.035) 1px,transparent 1px),linear-gradient(90deg,rgba(23,107,135,.035) 1px,transparent 1px);background-size:34px 34px}}.shell{{max-width:1500px;margin:auto;padding:26px 32px 60px}}header{{border-bottom:2px solid var(--ink);padding-bottom:20px;display:flex;justify-content:space-between;gap:24px}}.kicker,.ui{{font:700 11px 'Segoe UI',sans-serif;letter-spacing:.14em;text-transform:uppercase;color:var(--teal)}}h1{{font-size:clamp(35px,5vw,68px);line-height:.98;font-weight:500;margin:10px 0;max-width:800px}}.lede,.intro{{color:var(--muted);font-size:17px;max-width:920px}}.meta{{font:12px 'Segoe UI',sans-serif;color:var(--muted);text-align:right}}.layout{{display:grid;grid-template-columns:220px 1fr;gap:28px;margin-top:25px}}nav{{position:sticky;top:15px;align-self:start;display:grid;gap:7px}}nav button,.control button{{border:1px solid var(--line);background:var(--panel);padding:10px 12px;text-align:left;cursor:pointer;color:var(--ink)}}nav button.active,nav button:hover,.control button.active{{background:var(--ink);color:white;border-color:var(--ink)}}.chapter{{display:none}}.chapter.active{{display:block;animation:up .3s ease}}@keyframes up{{from{{opacity:0;transform:translateY(8px)}}to{{opacity:1;transform:none}}}}h2{{font-size:37px;line-height:1.05;font-weight:500;margin:0 0 8px}}h3{{font-size:21px;font-weight:500;margin:27px 0 7px}}.flow,.cards{{display:grid;grid-template-columns:repeat(5,1fr);border-top:1px solid var(--ink);border-bottom:1px solid var(--ink);margin:24px 0}}.cards{{grid-template-columns:repeat(3,1fr);border:0;gap:10px}}.step,.card{{padding:15px;border-right:1px solid var(--line);background:rgba(255,253,248,.55)}}.step:last-child{{border:0}}.step b{{color:var(--teal);font:700 11px 'Segoe UI',sans-serif}}.step span{{display:block;margin-top:8px}}.card{{border:1px solid var(--line);background:var(--panel)}}.card b{{font-size:28px;font-weight:500;display:block;margin:5px 0}}.card small{{color:var(--muted);font:12px 'Segoe UI',sans-serif}}.note{{border-left:4px solid var(--teal);background:#e5efed;padding:13px 16px;color:#345057}}.actions,.control{{display:flex;gap:9px;align-items:center;flex-wrap:wrap;margin:17px 0}}.actions a{{color:var(--teal);font:13px 'Segoe UI',sans-serif;border-bottom:1px solid currentColor;text-decoration:none}}select{{border:1px solid var(--line);background:var(--panel);padding:10px;min-width:210px}}.chart{{background:var(--panel);border:1px solid var(--line);padding:14px;margin-top:14px}}svg{{display:block;width:100%;height:auto;min-height:290px}}.legend{{display:flex;gap:7px;flex-wrap:wrap;margin:0 0 10px}}.legend button{{border:1px solid var(--line);background:var(--panel);padding:6px 9px;cursor:pointer}}.legend button.off{{opacity:.38;text-decoration:line-through}}table{{border-collapse:collapse;width:100%;font:12px 'Segoe UI',sans-serif}}th,td{{padding:8px;border-bottom:1px solid var(--line);text-align:right}}th:first-child,td:first-child{{text-align:left}}.tablewrap{{overflow:auto;background:var(--panel);border:1px solid var(--line)}}.swatch{{display:inline-block;width:11px;height:11px;border:1px solid #89999e;margin-right:5px}}@media(max-width:850px){{.shell{{padding:18px 14px}}header,.layout{{display:block}}.meta{{text-align:left;margin-top:16px}}nav{{position:static;display:flex;overflow:auto;margin-bottom:20px}}nav button{{white-space:nowrap}}.flow,.cards{{grid-template-columns:1fr}}.step{{border-right:0;border-bottom:1px solid var(--line)}}}}
</style></head><body><div class="shell"><header><div><div class="kicker">Statistical factor risk model · research viewer</div><h1>From benchmark structure to residual alpha.</h1><p class="lede">A guided, interactive audit of the benchmark universe, frozen latent factors, fund hidden-beta decomposition, and the residual trend-following portfolio.</p></div><div class="meta">Offline HTML<br>Frozen OOS model<br>Data-driven controls</div></header><div class="layout"><nav><button class="active" data-tab="start">01 · Start here</button><button data-tab="universe">02 · Universes</button><button data-tab="factors">03 · Frozen factors</button><button data-tab="funds">04 · Funds</button><button data-tab="strategies">05 · Strategies</button><button data-tab="correlations">06 · Correlations</button></nav><main>
<section id="start" class="chapter active"><div class="kicker">Research map</div><h2>What is being explained, and what is left?</h2><p class="intro">Benchmark assets define the hidden risk space. Investible funds are held out from factor construction, regressed on the daily latent factor moves, and then stripped down to residual returns. The final strategy trades that residual panel.</p><div class="flow"><div class="step"><b>BENCHMARKS</b><span>Clustered assets define the risk vocabulary.</span></div><div class="step"><b>LOADINGS</b><span>Chunked PCA loadings are aligned, averaged, and frozen.</span></div><div class="step"><b>FACTOR MOVES</b><span>Daily benchmark regressions estimate latent innovations OOS.</span></div><div class="step"><b>FUNDS</b><span>Training betas explain OOS raw performance and residuals.</span></div><div class="step"><b>ALPHA</b><span>Equal-weight residuals feed the trend follower.</span></div></div><div id="summary" class="cards"></div><p class="note"><b>Reading guide:</b> begin with the universe map, inspect the frozen loadings and OOS factor moves, select a fund to see its hidden beta composition, then compare the raw and residual portfolios. Legend buttons are live controls: click any series to hide or restore it.</p></section>
<section id="universe" class="chapter"><div class="kicker">Chapter 02 · Inputs</div><h2>Two universes, two jobs.</h2><p class="intro">The benchmark panel is the only source of factor definitions. The non-benchmark universe is investible research material: funds are explained by the frozen benchmark model, never allowed to redefine it.</p><div class="cards"><article class="card"><span class="ui">Benchmark assets</span><b id="benchmarkCount"></b><small>ordered by hierarchical clustering of training correlations</small></article><article class="card"><span class="ui">Investible funds</span><b id="fundCount"></b><small>residuals are the input to the alpha sleeve</small></article><article class="card"><span class="ui">OOS observations</span><b id="obsCount"></b><small>daily factor moves and fund scores</small></article></div><h3>Clustered benchmark order</h3><div id="benchList" class="tablewrap"></div><p class="note">The ordering is descriptive, not a second model: hierarchical clustering makes the benchmark correlation structure readable before PCA defines the frozen factor space.</p></section>
<section id="factors" class="chapter"><div class="kicker">Chapter 03 · Frozen factor model</div><h2>Loadings first. Factor moves second.</h2><p class="intro">Historical benchmark blocks are decomposed, aligned, and averaged. That loading matrix is frozen. Each OOS day is then projected onto it by a linear regression of benchmark returns against the frozen loadings.</p><div class="actions"><a href="frozen_factor_loadings.csv">Frozen loading matrix CSV</a><a href="oos_latent_factor_moves.csv">OOS factor moves CSV</a></div><div id="loadingTable" class="tablewrap"></div><div class="chart"><div id="factorLegend" class="legend"></div><svg id="factorChart" viewBox="0 0 1000 380"></svg></div></section>
<section id="funds" class="chapter"><div class="kicker">Chapter 04 · Hidden betas</div><h2>Choose a fund. See the explanation.</h2><p class="intro">The dropdown drives one chart and one decomposition table. Raw performance is separated into the factor-fitted component and the unexplained residual. Toggle raw, fitted, and residual series independently.</p><div class="control"><label class="ui" for="fundSelect">Fund</label><select id="fundSelect"></select></div><div id="fundLegend" class="legend"></div><div class="chart"><svg id="fundChart" viewBox="0 0 1000 430"></svg></div><div id="betaTable" class="tablewrap"></div></section>
<section id="strategies" class="chapter"><div class="kicker">Chapter 05 · Portfolio construction</div><h2>Equal-weight funds, then trend follow.</h2><p class="intro">The equal-weight raw fund benchmark is shown beside the equal-weight residual fund benchmark and the residual trend follower. All strategy inputs are OOS fund returns; the trend signal and volatility estimate are lagged one day.</p><div id="strategyLegend" class="legend"></div><div class="chart"><svg id="strategyChart" viewBox="0 0 1000 430"></svg></div><div id="strategyTable" class="tablewrap"></div><div class="actions"><a href="figures/residual_alpha_trend_follower.html">Detailed alpha strategy report</a><a href="alpha_backtest_stats.csv">Alpha statistics CSV</a></div></section>
<section id="correlations" class="chapter"><div class="kicker">Chapter 06 · Correlation movement</div><h2>What changes when hidden beta is removed?</h2><p class="intro">Each point is a fund pair. The x-axis is raw correlation, the y-axis is residual correlation, and color shows the movement: red means correlation increased, blue means it decreased. Every point has a border so near-white movements remain visible.</p><div class="chart"><svg id="scatter" viewBox="0 0 1000 620"></svg></div></section>
</main></div></div><script>const DATA={data};
const $=id=>document.getElementById(id), colors=['#176b87','#2f855a','#b87919','#b94a48','#2e67a5','#6b4f9e','#127c78','#9a5b13'];
let fundIndex=0, fundVisible=[true,true,true], factorVisible=[], strategyVisible=[true,true,true];
function esc(s){{return String(s).replace(/[&<>"']/g,m=>({{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}}[m]))}}
function cumulative(rows,col,kind){{let v=1,out=[]; for(const r of rows){{v*=1+(r[col]||0);out.push(v)}} return out}}
function path(values,min,max){{const n=values.length-1; return values.map((v,i)=>`${62+876*i/Math.max(1,n)},${42+350*(max-v)/Math.max(1e-9,max-min)}`).join(' ')}}
function chart(svgId, series, visible, legendId){{const svg=$(svgId), keys=Object.keys(series), vals=keys.flatMap(k=>visible[k]?series[k]:[]).filter(Number.isFinite), min=Math.min(...vals),max=Math.max(...vals); svg.innerHTML=''; $(legendId).innerHTML=''; keys.forEach((k,i)=>{{const b=document.createElement('button');b.className=visible[k]?'':'off';b.innerHTML=`<span class="swatch" style="background:${{colors[i%colors.length]}}"></span>${{esc(k)}}`;b.onclick=()=>{{visible[k]=!visible[k];chart(svgId,series,visible,legendId)}};$(legendId).appendChild(b); if(!visible[k])return; const p=document.createElementNS('http://www.w3.org/2000/svg','polyline');p.setAttribute('points',path(series[k],min,max));p.setAttribute('fill','none');p.setAttribute('stroke',colors[i%colors.length]);p.setAttribute('stroke-width','3');svg.appendChild(p)}}); const line=document.createElementNS('http://www.w3.org/2000/svg','line');line.setAttribute('x1',62);line.setAttribute('x2',938);line.setAttribute('y1',392);line.setAttribute('y2',392);line.setAttribute('stroke','#9ca8a8');svg.appendChild(line)}}
function renderFund(){{const f=DATA.funds,n=f.names[fundIndex],rows=f.dates.map((date,i)=>({{raw:f.raw[i][fundIndex],fitted:f.fitted[i][fundIndex],residual:f.residual[i][fundIndex]}}));chart('fundChart',{{'Raw performance':cumulative(rows,'raw'), 'Factor-fitted performance':cumulative(rows,'fitted'),'Residual performance':cumulative(rows,'residual')}},{{'Raw performance':fundVisible[0],'Factor-fitted performance':fundVisible[1],'Residual performance':fundVisible[2]}},'fundLegend'); const b=f.betas[n]||{{}}; let h='<table><thead><tr><th>Hidden beta component</th><th>Loading</th><th>Annual return contribution</th></tr></thead><tbody>'; Object.entries(b).filter(([k])=>k.startsWith('beta_')||k==='alpha').forEach(([k,v])=>h+=`<tr><td>${{esc(k)}}</td><td>${{Number(v).toFixed(4)}}</td><td>${{k==='alpha'?'—':'model factor move'}}</td></tr>`); h+=`<tr><td>Residual</td><td>—</td><td>Unexplained OOS return</td></tr></tbody></table>`; $('betaTable').innerHTML=h}}
function renderScatter(){{const s=DATA.scatter,svg=$('scatter');svg.innerHTML='<line x1="70" y1="550" x2="950" y2="550" stroke="#17282e"/><line x1="70" y1="40" x2="70" y2="550" stroke="#17282e"/><text x="500" y="610" text-anchor="middle">Raw correlation</text><text x="18" y="300" transform="rotate(-90 18 300)">Residual correlation</text>'; for(const p of s){{const x=70+880*(p.raw+1)/2,y=550-510*(p.residual+1)/2,t=Math.max(-1,Math.min(1,p.delta)),r=t>0?Math.round(185+70*t):Math.round(46+80*(1+t)),g=t>0?Math.round(74+100*(1-t)):Math.round(103+100*(1+t)),b=t>0?Math.round(72+100*(1-t)):Math.round(165+70*t);const c=document.createElementNS('http://www.w3.org/2000/svg','circle');c.setAttribute('cx',x);c.setAttribute('cy',y);c.setAttribute('r',6);c.setAttribute('fill',`rgb(${{r}},${{g}},${{b}})`);c.setAttribute('stroke','#53636a');c.setAttribute('stroke-width','1.5');c.innerHTML=`<title>${{p.a}} / ${{p.b}} · raw ${{p.raw.toFixed(2)}} · residual ${{p.residual.toFixed(2)}} · change ${{p.delta.toFixed(2)}}</title>`;svg.appendChild(c)}}}}
function init(){{const f=DATA.funds;f.names.forEach((n,i)=>$('fundSelect').add(new Option(n,n)));$('fundSelect').onchange=e=>{{fundIndex=f.names.indexOf(e.target.value);renderFund()}};$('benchmarkCount').textContent=DATA.benchmarks.length;$('fundCount').textContent=f.names.length;$('obsCount').textContent=f.dates.length;$('benchList').innerHTML='<table><thead><tr><th>Cluster order</th><th>Benchmark asset</th></tr></thead><tbody>'+DATA.benchmarks.map((x,i)=>`<tr><td>${{i+1}}</td><td>${{x}}</td></tr>`).join('')+'</tbody></table>';let h='<table><thead><tr><th>Asset</th>'+DATA.factors.names.map(x=>`<th>${{x}}</th>`).join('')+'</tr></thead><tbody>';DATA.benchmarks.forEach(x=>h+=`<tr><td>${{x}}</td>${{DATA.factors.names.map((_,j)=>`<td>${{x}}</td>`).join('')}}</tr>`);$('loadingTable').innerHTML=h+'</tbody></table>';factorVisible=Object.fromEntries(DATA.factors.names.map(x=>[x,true]));const fr=DATA.factors.names.map((x,j)=>DATA.factors.values.map(r=>r[j]).reduce((a,v)=>a+v,0));chart('factorChart',Object.fromEntries(DATA.factors.names.map((x,j)=>[x,DATA.factors.values.map(r=>r[j])])),factorVisible,'factorLegend');const rows=f.dates.map((_,i)=>{{const raw=f.raw[i].reduce((a,v)=>a+v,0)/f.names.length,res=f.residual[i].reduce((a,v)=>a+v,0)/f.names.length;return{{raw,res,alpha:0}}}});const alpha=DATA.alpha[0]||{{}};const ar=cumulative(rows,'alpha');chart('strategyChart',{{'Equal-weight raw funds':cumulative(rows,'raw'),'Equal-weight residual funds':cumulative(rows,'residual'),'Residual alpha trend follower':ar}},{{'Equal-weight raw funds':true,'Equal-weight residual funds':true,'Residual alpha trend follower':true}},'strategyLegend');$('strategyTable').innerHTML='<table><thead><tr><th>Strategy</th><th>Target vol</th><th>Realized vol</th><th>CAGR</th><th>Max drawdown</th><th>Sharpe</th></tr></thead><tbody>'+DATA.stats.map(r=>`<tr><td>${{r.strategy}}</td><td>${{(r.target_vol*100).toFixed(1)}}%</td><td>${{(r.annual_vol*100).toFixed(1)}}%</td><td>${{(r.cagr*100).toFixed(1)}}%</td><td>${{(r.max_drawdown*100).toFixed(1)}}%</td><td>${{r.sharpe.toFixed(2)}}</td></tr>`).join('')+`<tr><td>Residual alpha trend follower</td><td>${{(alpha.target_vol*100).toFixed(1)}}%</td><td>${{(alpha.annual_vol*100).toFixed(1)}}%</td><td>${{(alpha.cagr*100).toFixed(1)}}%</td><td>${{(alpha.max_drawdown*100).toFixed(1)}}%</td><td>${{alpha.sharpe.toFixed(2)}}</td></tr></tbody></table>`;renderFund();renderScatter()}}const buttons=[...document.querySelectorAll('nav button')],chapters=[...document.querySelectorAll('.chapter')];buttons.forEach(b=>b.onclick=()=>{{buttons.forEach(x=>x.classList.toggle('active',x===b));chapters.forEach(c=>c.classList.toggle('active',c.id===b.dataset.tab));history.replaceState(null,'','#'+b.dataset.tab)}});init();</script></body></html>'''

def main() -> None:
    OUTPUT.write_text(render(build_payload()), encoding="utf-8")
    print(f"Wrote {OUTPUT.resolve()} ({OUTPUT.stat().st_size / 1024:.1f} KB)")
if __name__ == "__main__": main()
